        (bool) preg_match('/' . preg_quote($bpKopf, '/') . '\n- /', $bpKnapp));
}
pruefe('ein unbeantworteter Bestand wird ausdrücklich benannt',
    str_contains($bpKnapp, 'ob es eine alte Seite gibt'));
