$efAlt = (string) Db::wert('SELECT antworten FROM bedarf WHERE id = ?', [$efBid], '');
$efPflege = [];
foreach (['ja' => 'du', 'vielleicht' => 'offen', 'nein' => null] as $efBet => $efSoll) {
