    'messwerte' => ['lcp_ms' => 6200, 'cls' => 0.12], 'sprache' => 'it', 'experience' => 'Una breve sequenza video dei piatti in apertura.']);
$akF = Db::one('SELECT * FROM akq_firmen WHERE id = ?', [$akA['id']]);
