$akNull = null;
try { AkquiseText::erzeugen($akF, $akAud, [], 'de'); } catch (RuntimeException $e) { $akNull = $e->getMessage(); }
pruefe('ohne belegten Befund entsteht kein Text', $akNull !== null);

$akV1 = AkquiseVersand::regelVorlage($akA['id'], 'it', 'email');
