Db::run('UPDATE akq_termine SET beginn = ?, ende = ? WHERE id = ?', [date('Y-m-d H:i:s', time() + 20 * 3600), date('Y-m-d H:i:s', time() + 20 * 3600 + 1800), (int) $tmT['id']]);
